520		Type    string `yaml:"type"`              // http, https, icmp, dns
521		Target  string `yaml:"target"`            // URL, IP, or hostname
522		Timeout int    `yaml:"timeout,omitempty"` // In seconds
523	
524		// Legacy support
525		URL string `yaml:"url,omitempty"` // Deprecated, use Target
526	
527		// ICMP specific
528		Count int `yaml:"count,omitempty"` // Number of pings
529	
530		// DNS specific
531		Nameserver string `yaml:"nameserver,omitempty"` // Custom DNS server
532	}
533	
534	// Load loads the configuration from the current context
535	func Load() (*Config, error) {
536		ctx, err := GetCurrentContext()
537		if err != nil {
538			// Fallback to default on error
539			ctx = "default"
540		}
541	
542		cfg, err := LoadContext(ctx)
543		if err != nil {
544			// If the file does not exist, return the default config
545			if os.IsNotExist(err) || errors.Is(err, ErrContextNotFound) {
546				return Default(), nil
547			}
548			// Otherwise (parsing error, permission error, etc.), propagate the error
549			return nil, err
550		}
551	
552		return cfg, nil
553	}
554	
555	// applyDefaults applies the default values to a configuration.
556	// Returns an error when the file cannot be normalized — today
557	// only for registries (duplicate slug, missing parent group).
558	func applyDefaults(cfg *Config) error {
559		homeDir, _ := os.UserHomeDir()
560	
561		// `gitlab:` → `forge:`, and it runs **first**. That is not tidiness: every
562		// default below writes into cfg.Forge, so a migration placed after them
563		// would find a block that is no longer empty and take the field-by-field
564		// path — where every field is already filled with a default, and the user's
565		// own `parallel_jobs: 7` is silently dropped. Measured, not theorised: it
566		// is what the first draft did, and the retired-keys test caught it.
567		//
568		// The other half of the reason is `docker:` → `network:`'s: yaml.Unmarshal
569		// is not strict here, so an un-migrated block is dropped in silence, and the
570		// silence would point a context at no host at all.
571		migrateGitLabSection(cfg)
572		// Before the defaults for the same reason: a default source written first
573		// would read as a value the file already carried, and the legacy one would
574		// be dropped.
575		migrateScanSection(&cfg.Scan)
576	
577		// "dark" was a third name for the built-in theme: LoadTheme accepts "",
578		// "dark" and "default" alike, but ListThemes only ever offers "default", so
579		// a config saying "dark" named a theme no picker could show. Normalised at
580		// load; LoadTheme still accepts the old name for a file not yet rewritten.
581		if cfg.App.Theme == "" || cfg.App.Theme == "dark" {
582			cfg.App.Theme = ThemeDefault
583		}
584		if cfg.App.LogFile == "" {
585			cfg.App.LogFile = filepath.Join(homeDir, ".devdesk", "devdesk.log")
586		}
587		if cfg.App.DefaultView == "" {
588			cfg.App.DefaultView = "dashboard"
589		}
590		if cfg.App.WorkspacesDir == "" {
591			cfg.App.WorkspacesDir = filepath.Join(homeDir, "workspaces")
592		}
593		if cfg.App.IDECommand == "" {
594			cfg.App.IDECommand = "code"
595		}
596		// Left empty, credentials.Select already treats this as "auto"; naming it
597		// keeps the setting inside the closed set the configuration view cycles
598		// through, so the first arrow press does not jump somewhere arbitrary.
599		if cfg.App.SecretBackend == "" {
600			cfg.App.SecretBackend = "auto"
601		}
602		// Same reason: engine.Resolve reads "" as auto, but the configuration view
603		// cycles a closed set and a value outside it has nowhere to start from.
604		if cfg.App.ContainerEngine == "" {
605			cfg.App.ContainerEngine = EngineAuto
606		}
607		// Same reason: the configuration view cycles a closed set.
608		if cfg.App.GaugeGlyph == "" {
609			cfg.App.GaugeGlyph = GaugeGlyphShade
610		}
611		warnInvalidMotion(cfg.App)
612		warnInvalidWhenUnfocused(cfg.App)
613		// Written rather than left empty for the reason above: the configuration
614		// view cycles a closed set. A value outside it is left alone — remediation
615		// reads it as same-line — so a typo in the file is not silently rewritten.
616		if cfg.Scan.BaseImageTrack == "" {
617			cfg.Scan.BaseImageTrack = BaseImageTrackSameLine
618		}
619		if cfg.Scan.ImageVerification == "" {
620			cfg.Scan.ImageVerification = ImageVerificationOn
621		}
622		if cfg.Status.RefreshInterval == 0 {
623			cfg.Status.RefreshInterval = 10
624		}
625		if cfg.Status.Timeout == 0 {
626			cfg.Status.Timeout = 5
627		}
628		if cfg.Forge.Type == "" {
629			cfg.Forge.Type = ForgeGitLab
630		}
631		if cfg.Forge.DefaultVisibility == "" {
632			cfg.Forge.DefaultVisibility = "private"
633		}
634		if cfg.Forge.CloneMethod == "" {
635			cfg.Forge.CloneMethod = "https"
636		}
637		if cfg.Forge.Pull.ParallelJobs == 0 {
638			cfg.Forge.Pull.ParallelJobs = 4
639		}
640		if cfg.Registry.CacheDir == "" {
641			cfg.Registry.CacheDir = filepath.Join(homeDir, ".devdesk", "cache", "templates")
642		}
643		// Migrate old single-registry config to the new Registries list
644		if cfg.Registry.URL != "" && len(cfg.Registry.Registries) == 0 {
645			cfg.Registry.Registries = []RegistryItem{{
646				URL:      cfg.Registry.URL,
647				Username: cfg.Registry.Username,
648				AuthMode: AuthCredentials,
649			}}
650		}
651		if cfg.Scan.CacheDir == "" {
652			cfg.Scan.CacheDir = filepath.Join(homeDir, ".devdesk", "cache", "scans")
653		}
654		if cfg.Scan.MaxCachedReports == 0 {
655			cfg.Scan.MaxCachedReports = 50
656		}
657		if cfg.Scan.Timeout == 0 {
658			cfg.Scan.Timeout = 300
659		}
660		if cfg.Scan.MaxConcurrentScans == 0 {
661			cfg.Scan.MaxConcurrentScans = 3
662		}
663		// An address the file does not carry is the default, never "nowhere":
664		// a bind that silently does not happen would look exactly like a server
665		// that is off, and `mcp.enabled` is what answers that question.
666		if cfg.MCP.Listen == "" {
667			cfg.MCP.Listen = DefaultMCPListen
668		}
669	
670		// Auto is the historical resolution, so a config that predates the setting
671		// keeps behaving exactly as it did.
672		for _, id := range ToolIDs() {
673			if tool := cfg.Scan.Tools.Tool(id); tool.Source == "" {
674				tool.Source = ToolSourceAuto
675			}
676		}
677		if cfg.Scan.Tools.Kubeconform.KubernetesVersion == "" {
678			cfg.Scan.Tools.Kubeconform.KubernetesVersion = DefaultKubernetesVersion
679		}
680	
681		if cfg.Network.CheckTimeout == 0 {
682			cfg.Network.CheckTimeout = DefaultCheckTimeout
683		}
684		if cfg.Network.PingCount == 0 {
685			cfg.Network.PingCount = DefaultPingCount
686		}
687		if cfg.Network.CertExpiryWarnDays == 0 {
688			cfg.Network.CertExpiryWarnDays = DefaultCertExpiryWarnDays
689		}
690		if cfg.Network.PortsRefreshInterval == 0 {
691			cfg.Network.PortsRefreshInterval = DefaultPortsRefreshInterval
692		}
693		cfg.Network.ProxyPort = normalizeProxyPort(cfg.Network.ProxyPort)
694	
695		// A file with no `categories:` at all — new, or written before any scan
696		// option existed — scans for what a new context does. A block that is
697		// present is an answer, even with everything off, and is left alone: the
698		// "all off means never configured" reading of the old switches lives in the
699		// migration, which is the only place that still sees them.
700		if cfg.Scan.Categories.isZero() {
701			cfg.Scan.Categories = DefaultScanCategories()
702		}
703	
