770	// normalizeProxyPort returns the port to serve on: the default for a file that
771	// does not say, and the default — loudly — for one that states a port the
772	// proxy cannot bind. Unlike the other network dials, a wrong value here is not
773	// merely a slow probe: it would make every named route unbindable.
774	func normalizeProxyPort(port int) int {
775		switch {
776		case port == 0:
777			return DefaultProxyPort
778		case port < MinProxyPort || port > MaxProxyPort:
779			log.Printf("WARN [config] network.proxy_port %d is outside %d-%d, using %d",
780				port, MinProxyPort, MaxProxyPort, DefaultProxyPort)
781			return DefaultProxyPort
782		}
783		return port
784	}
