918	// LoadContext loads the configuration for a specific context
919	// contextName = "default" -> config.yaml
920	// contextName = "dev" -> config-dev.yaml
921	func LoadContext(contextName string) (*Config, error) {
922		if err := ValidateContextName(contextName); err != nil {
923			return nil, err
924		}
925	
926		configPath, err := GetContextPath(contextName)
927		if err != nil {
928			return nil, err
929		}
930	
931		// Check whether the file exists
932		if _, err := os.Stat(configPath); os.IsNotExist(err) {
933			return nil, fmt.Errorf("context '%s' does not exist (no file at %s): %w", contextName, configPath, ErrContextNotFound)
934		}
935	
936		// Read and parse YAML
937		data, err := os.ReadFile(configPath)
938		if err != nil {
939			return nil, err
940		}
941	
942		var cfg Config
943		if err := yaml.Unmarshal(data, &cfg); err != nil {
944			return nil, fmt.Errorf("failed to parse context '%s': %w", contextName, err)
945		}
946	
947		// Apply the default values
948		if err := applyDefaults(&cfg); err != nil {
949			return nil, fmt.Errorf("invalid context '%s': %w", contextName, err)
950		}
951	
952		// Expand paths (tildes)
953		if home, err := os.UserHomeDir(); err == nil {
954			cfg.ExpandPaths(home)
955		}
956	
957		return &cfg, nil
958	}
959	
960	// ExpandPaths expands tildes (~) in configuration paths
961	func (c *Config) ExpandPaths(homeDir string) {
962		expand := func(path string) string {
963			if strings.HasPrefix(path, "~/") {
964				return filepath.Join(homeDir, path[2:])
965			}
966			return path
967		}
968	
969		c.App.LogFile = expand(c.App.LogFile)
970		c.App.WorkspacesDir = expand(c.App.WorkspacesDir)
971		c.Registry.CacheDir = expand(c.Registry.CacheDir)
972		c.Scan.CacheDir = expand(c.Scan.CacheDir)
973		for _, id := range ToolIDs() {
974			tool := c.Scan.Tools.Tool(id)
975			tool.Binary = expand(tool.Binary)
976			tool.Config = absolute(expand(tool.Config))
977		}
978	}
979	
980	// absolute pins a configured file path to one meaning.
981	//
982	// A relative gitleaks_config does not mean the same thing on both sides of the
983	// Docker boundary — DevDesk's working directory in binary mode, the container's
984	// in Docker mode — and the file is now mounted, so the two readings would
985	// disagree about which file is scanned with. Resolving it here settles it
986	// against DevDesk's own working directory, once, at load: the path that gets
987	// mounted and the path the configuration view shows are then the same string.
988	//
989	// A path that cannot be resolved is left as it was rather than dropped:
990	// RunGitleaks refuses an unreadable config with the reason, and that is a
991	// better place to fail than a config file that silently loses a setting.
992	func absolute(path string) string {
993		if path == "" {
994			return ""
995		}
996		abs, err := filepath.Abs(path)
997		if err != nil {
998			return path
999		}
1000		return abs
1001	}
