1003	// SaveContext saves the configuration to a specific context file
1004	func SaveContext(cfg *Config, contextName string) error {
1005		if err := ValidateContextName(contextName); err != nil {
1006			return err
1007		}
1008	
1009		configPath, err := GetContextPath(contextName)
1010		if err != nil {
1011			return err
1012		}
1013	
1014		// Ensure the directory exists
1015		if err := EnsureConfigDir(); err != nil {
1016			return err
1017		}
1018	
1019		// Marshal to YAML
1020		data, err := yaml.Marshal(cfg)
1021		if err != nil {
1022			return err
1023		}
1024	
1025		// Write the file
1026		return os.WriteFile(configPath, data, 0600)
