1051	// GetContextPath returns the file path for a context
1052	// "default" -> ~/.devdesk/config.yaml
1053	// "dev" -> ~/.devdesk/config-dev.yaml
1054	func GetContextPath(contextName string) (string, error) {
1055		homeDir, err := os.UserHomeDir()
1056		if err != nil {
1057			return "", err
1058		}
1059	
1060		configDir := filepath.Join(homeDir, ".devdesk")
1061	
1062		var filename string
1063		if contextName == "default" {
1064			filename = "config.yaml"
1065		} else {
1066			filename = fmt.Sprintf("config-%s.yaml", contextName)
1067		}
1068	
1069		return filepath.Join(configDir, filename), nil
1070	}
1071	
1072	// ValidateContextName validates the format of the context name
1073	// Must be "default" or match ^[a-z0-9-]+$
1074	func ValidateContextName(name string) error {
1075		if name == "default" {
1076			return nil
1077		}
1078	
1079		// Pattern: lowercase letters, digits, hyphens
1080		matched, err := regexp.MatchString("^[a-z0-9-]+$", name)
1081		if err != nil {
1082			return err
1083		}
1084	
1085		if !matched {
1086			return fmt.Errorf("invalid context name '%s': must contain only lowercase letters, numbers, and hyphens", name)
1087		}
1088	
1089		return nil
1090	}
1091	
1092	// Sentinel errors for context management; callers match them with errors.Is.
1093	var (
1094		// ErrReservedContextName reports a name that cannot be used for a new context.
1095		ErrReservedContextName = errors.New("reserved context name")
1096		// ErrContextExists reports an attempt to create a context that already exists.
1097		ErrContextExists = errors.New("context already exists")
1098		// ErrContextNotFound reports a context with no config file.
1099		ErrContextNotFound = errors.New("context not found")
1100	)
1101	
1102	// reservedContextNames are rejected when creating a context (they stay
1103	// loadable when a file already exists, so ValidateContextName accepts them).
1104	var reservedContextNames = []string{"-", "new", "list"}
1105	
1106	// ValidateNewContextName applies ValidateContextName, then refuses the
1107	// reserved names. Use it only when creating a context.
1108	func ValidateNewContextName(name string) error {
1109		if err := ValidateContextName(name); err != nil {
1110			return err
1111		}
1112		for _, r := range reservedContextNames {
1113			if name == r {
1114				return fmt.Errorf("%q is reserved — choose another name: %w", name, ErrReservedContextName)
1115			}
1116		}
1117		return nil
1118	}
1119	
1120	// CreateContext creates a new context with a default configuration
1121	// Empty monitors, empty GitLab URL, other values default
1122	func CreateContext(contextName string) error {
1123		if err := ValidateNewContextName(contextName); err != nil {
1124			return err
1125		}
1126	
1127		// Check whether it already exists
1128		exists, err := ContextExists(contextName)
1129		if err != nil {
1130			return err
1131		}
1132		if exists {
1133			return fmt.Errorf("context '%s' already exists: %w", contextName, ErrContextExists)
1134		}
1135	
1136		// Create config with defaults
1137		cfg := Default()
1138	
1139		// Clear monitors and forge for the new context
1140		cfg.Status.Components = []ComponentConfig{}
1141		cfg.Forge.URL = ""
1142	
1143		// Save
1144		return SaveContext(cfg, contextName)
1145	}
