555	// applyDefaults applies the default values to a configuration.
556	// Returns an error when the file cannot be normalized — today
557	// only for registries (duplicate slug, missing parent group).
558	func applyDefaults(cfg *Config) error {
559		homeDir, _ := os.UserHomeDir()
560	
561		// `gitlab:` → `forge:`, and it runs **first**. That is not tidiness: every
562		// default below writes into cfg.Forge, so a migration placed after them
563		// would find a block that is no longer empty and take the field-by-field
564		// path — where every field is already filled with a default, and the user's
565		// own `parallel_jobs: 7` is silently dropped. Measured, not theorised: it
566		// is what the first draft did, and the retired-keys test caught it.
567		//
568		// The other half of the reason is `docker:` → `network:`'s: yaml.Unmarshal
569		// is not strict here, so an un-migrated block is dropped in silence, and the
570		// silence would point a context at no host at all.
571		migrateGitLabSection(cfg)
572		// Before the defaults for the same reason: a default source written first
573		// would read as a value the file already carried, and the legacy one would
574		// be dropped.
575		migrateScanSection(&cfg.Scan)
576	
577		// "dark" was a third name for the built-in theme: LoadTheme accepts "",
578		// "dark" and "default" alike, but ListThemes only ever offers "default", so
579		// a config saying "dark" named a theme no picker could show. Normalised at
580		// load; LoadTheme still accepts the old name for a file not yet rewritten.
581		if cfg.App.Theme == "" || cfg.App.Theme == "dark" {
582			cfg.App.Theme = ThemeDefault
583		}
584		if cfg.App.LogFile == "" {
585			cfg.App.LogFile = filepath.Join(homeDir, ".devdesk", "devdesk.log")
586		}
587		if cfg.App.DefaultView == "" {
