598		// through, so the first arrow press does not jump somewhere arbitrary.
599		if cfg.App.SecretBackend == "" {
600			cfg.App.SecretBackend = "auto"
601		}
602		// Same reason: engine.Resolve reads "" as auto, but the configuration view
603		// cycles a closed set and a value outside it has nowhere to start from.
604		if cfg.App.ContainerEngine == "" {
