1	package config
2	
3	import (
4		"math"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// loadAgentUsageYAML writes raw YAML as the "default" context under an isolated HOME
12	// and returns the loaded result.
13	func loadAgentUsageYAML(t *testing.T, body string) (*Config, error) {
14		t.Helper()
15		home := setupTmpHome(t)
16		dir := filepath.Join(home, ".devdesk")
17		if err := os.MkdirAll(dir, 0o700); err != nil {
18			t.Fatal(err)
19		}
20		if err := os.WriteFile(filepath.Join(dir, "config.yaml"), []byte(body), 0o600); err != nil {
21			t.Fatal(err)
22		}
23		return LoadContext("default")
24	}
25	
26	func wantRate(t *testing.T, name string, r Rate, want float64, wantState RateState) {
27		t.Helper()
28		got, st := r.Value()
29		if st != wantState {
30			t.Errorf("%s: state = %v, want %v", name, st, wantState)
31		}
32		if wantState == RateSet && got != want {
33			t.Errorf("%s: value = %v, want %v", name, got, want)
34		}
35	}
36	
37	func TestAgentUsagePrices_FullEntry(t *testing.T) {
38		cfg, err := loadAgentUsageYAML(t, `
39	agent_usage:
40	  prices:
41	    claude-x:
42	      input: 5
43	      output: 25.5
44	      cache_write_5m: 6.25
45	      cache_write_1h: 10
46	      cache_read: 0
47	`)
48		if err != nil {
49			t.Fatalf("LoadContext: %v", err)
50		}
51		p, ok := cfg.AgentUsage.Prices["claude-x"]
52		if !ok {
53			t.Fatalf("entry missing: %#v", cfg.AgentUsage.Prices)
54		}
55		wantRate(t, "input (int)", p.Input, 5, RateSet)
56		wantRate(t, "output", p.Output, 25.5, RateSet)
57		wantRate(t, "cache_write_5m", p.CacheWrite5m, 6.25, RateSet)
58		wantRate(t, "cache_write_1h", p.CacheWrite1h, 10, RateSet)
59		wantRate(t, "cache_read explicit 0", p.CacheRead, 0, RateSet)
60	}
61	
62	func TestAgentUsagePrices_MissingRate(t *testing.T) {
63		cfg, err := loadAgentUsageYAML(t, "agent_usage:\n  prices:\n    m:\n      input: 1\n")
64		if err != nil {
65			t.Fatal(err)
66		}
67		p := cfg.AgentUsage.Prices["m"]
68		wantRate(t, "input", p.Input, 1, RateSet)
69		wantRate(t, "cache_read", p.CacheRead, 0, RateMissing)
70		wantRate(t, "output", p.Output, 0, RateMissing)
71	}
72	
73	// A badly typed or invalid rate costs its own entry, never the context load.
74	func TestAgentUsagePrices_InvalidRateDoesNotFailLoad(t *testing.T) {
75		cases := map[string]string{
76			"string":      `"5$"`,
77			"bare string": `abc`,
78			"list":        `[1, 2]`,
79			"map":         `{a: 1}`,
80			"bool":        `true`,
81			"null":        `~`,
